pt(9,'0.87','m','>=','As portas de entrada/saída dos edifícios e estabelecimentos devem ter um largura útil não inferior a 0,87 m','item 2.2.3',('2','2.2.3',None,'9'),'entrance and exit doors of buildings and establishments','Quantity: minimum clear width of an entrance or exit door, measured between the face of the open leaf and the stop on the opposite side; a door opened to 90 degrees if hinged or pivoting.')
pt(4,'1.2','m','>=','Os patamares, galerias e corredores devem possuir uma largura não inferior a 1,2 m.','item 2.3.1',('2','2.3.1',None,'9'),'landings, galleries and corridors','Quantity: minimum width of a landing, gallery or corridor.')
pt(4,'0.9','m','>=','Podem existir troços dos patamares, galerias ou corredores com uma largura não inferior a 0,9 m, se o seu comprimento for inferior a 1,5 m e se não derem acesso a portas laterais de espaços acessíveis.','item 2.3.2',('2','2.3.2',None,'9'),'short segments of landings, galleries or corridors, under 1.5 m long and giving no access to side doors','Quantity: reduced width permitted for a short segment. A permission (podem existir), so the comparator records the stated floor only.')
for k in rows:
    lang=k.get('lang','en')
    c=['python3','scripts/db.py','add-extraction','--ref-id',k['ref'],'--parameter-id',str(k['p']),'--identity',k['lens'],'--claim-type',k.get('ctype','numerical'),'--claim-text',k['quote'],'--source-section',k['sec'],'--jurisdiction',k['jur'],'--setting',k['setting'],'--extraction-method','skim','--extraction-status','preliminary','--figure-role',k['role'],'--relation','none','--locator-scheme',k['ls'],'--loc-section',k['loc'][0],'--loc-note',k['locnote'],'--notes',k['note'],'--session',SESS]
    if k.get('val'): c+=['--claimed-value',k['val'],'--claimed-unit',k['unit']]
    if k.get('cmp'): c+=['--comparator',k['cmp']]
    if k['loc'][1]: c+=['--loc-paragraph',k['loc'][1]]
    if k['loc'][2]: c+=['--loc-clause',k['loc'][2]]
    if DRY: c.append('--dry-run')
    o=subprocess.run(c,env={**os.environ,'GUIDEBOOK_DB_PATH':DB},capture_output=True,text=True)
    ok='"extraction_id"' in o.stdout
    print(k['ref'],k['p'],k.get('val'),k.get('unit'),'OK' if ok else 'FAIL '+' | '.join((o.stdout+o.stderr).strip().splitlines()[-2:])[:400])
